const BmapRemade *bmap_remade_find(const char *name)
{
    size_t i;

    for (i = 0; i < sizeof k_remade / sizeof k_remade[0]; i++) {
        if (strcmp(k_remade[i].name, name) == 0) {
            return &k_remade[i];
        }
    }
    return NULL;
}
